CREATE TABLE public.crm_catalogs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text NOT NULL, parent_id uuid REFERENCES public.crm_catalogs(id), name text NOT NULL, description text NOT NULL DEFAULT '', sort_order integer NOT NULL DEFAULT 0, active boolean NOT NULL DEFAULT true, config jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.crm_catalogs TO authenticated; GRANT ALL ON public.crm_catalogs TO service_role;
ALTER TABLE public.crm_catalogs ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.crm_access_grants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, permission text NOT NULL, started_at timestamptz NOT NULL DEFAULT now(), ended_at timestamptz, reason text NOT NULL, granted_by uuid NOT NULL, revoked_at timestamptz);
GRANT SELECT ON public.crm_access_grants TO authenticated; GRANT ALL ON public.crm_access_grants TO service_role;
ALTER TABLE public.crm_access_grants ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.crm_customers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE DEFAULT ('CRM-' || upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))), owner_id uuid NOT NULL, profile_kind text NOT NULL DEFAULT 'organization', name text NOT NULL, phone text NOT NULL DEFAULT '', tax_code text NOT NULL DEFAULT '', email text NOT NULL DEFAULT '', website text NOT NULL DEFAULT '', legal_name text NOT NULL DEFAULT '', province_code text, ward_code text, address text NOT NULL DEFAULT '', group_id uuid REFERENCES public.crm_catalogs(id), segment_id uuid REFERENCES public.crm_catalogs(id), priority_id uuid REFERENCES public.crm_catalogs(id), relationship_id uuid REFERENCES public.crm_catalogs(id), source_id uuid REFERENCES public.crm_catalogs(id), related_ids uuid[] NOT NULL DEFAULT '{}', details jsonb NOT NULL DEFAULT '{}', note text NOT NULL DEFAULT '', archived_at timestamptz, revision integer NOT NULL DEFAULT 1, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), request_key uuid NOT NULL, UNIQUE(created_by,request_key));
GRANT SELECT ON public.crm_customers TO authenticated; GRANT ALL ON public.crm_customers TO service_role;
ALTER TABLE public.crm_customers ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.crm_contacts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES public.crm_customers(id), name text NOT NULL, phone text NOT NULL DEFAULT '', zalo text NOT NULL DEFAULT '', email text NOT NULL DEFAULT '', title text NOT NULL DEFAULT '', department text NOT NULL DEFAULT '', role_ids uuid[] NOT NULL DEFAULT '{}', preferred_channel text NOT NULL DEFAULT 'phone', note text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT true, is_primary boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.crm_contacts TO authenticated; GRANT ALL ON public.crm_contacts TO service_role;
ALTER TABLE public.crm_contacts ENABLE ROW LEVEL SECURITY;
CREATE UNIQUE INDEX crm_one_primary_contact ON public.crm_contacts(customer_id) WHERE is_primary;
CREATE TABLE public.crm_locations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES public.crm_customers(id), label text NOT NULL DEFAULT 'Văn phòng', province_code text, ward_code text, address text NOT NULL DEFAULT '', is_primary boolean NOT NULL DEFAULT false, active boolean NOT NULL DEFAULT true);
GRANT SELECT ON public.crm_locations TO authenticated; GRANT ALL ON public.crm_locations TO service_role;
ALTER TABLE public.crm_locations ENABLE ROW LEVEL SECURITY;
CREATE UNIQUE INDEX crm_one_primary_location ON public.crm_locations(customer_id) WHERE is_primary;
CREATE TABLE public.crm_schedules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES public.crm_customers(id), contact_id uuid REFERENCES public.crm_contacts(id), kind text NOT NULL, goal text NOT NULL DEFAULT '', content text NOT NULL DEFAULT '', channel text NOT NULL DEFAULT 'phone', interval_days integer, fixed_weekday integer, due_at timestamptz NOT NULL, original_due_at timestamptz NOT NULL, reminder_days integer NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'pending', owner_id uuid NOT NULL, department_id uuid, attributed_at timestamptz NOT NULL DEFAULT now(), processed_at timestamptz, completed_at timestamptz, revision integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid NOT NULL, request_key uuid NOT NULL, UNIQUE(created_by,request_key));
GRANT SELECT ON public.crm_schedules TO authenticated; GRANT ALL ON public.crm_schedules TO service_role;
ALTER TABLE public.crm_schedules ENABLE ROW LEVEL SECURITY;
CREATE INDEX crm_due_owner ON public.crm_schedules(owner_id,status,due_at);
CREATE TABLE public.crm_interactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES public.crm_customers(id), schedule_id uuid REFERENCES public.crm_schedules(id), contact_id uuid REFERENCES public.crm_contacts(id), actor_id uuid NOT NULL, owner_id uuid NOT NULL, department_id uuid, channel text NOT NULL, outcome_id uuid NOT NULL REFERENCES public.crm_catalogs(id), connected boolean NOT NULL, completed boolean NOT NULL, content text NOT NULL, happened_at timestamptz NOT NULL DEFAULT now(), next_schedule_id uuid REFERENCES public.crm_schedules(id), request_key uuid NOT NULL, UNIQUE(actor_id,request_key));
GRANT SELECT ON public.crm_interactions TO authenticated; GRANT ALL ON public.crm_interactions TO service_role;
ALTER TABLE public.crm_interactions ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.crm_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid REFERENCES public.crm_customers(id), schedule_id uuid REFERENCES public.crm_schedules(id), actor_id uuid NOT NULL, action text NOT NULL, before_data jsonb, after_data jsonb, reason text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.crm_events TO authenticated; GRANT ALL ON public.crm_events TO service_role;
ALTER TABLE public.crm_events ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.crm_templates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid, name text NOT NULL, group_id uuid REFERENCES public.crm_catalogs(id), goal text NOT NULL DEFAULT '', channel text NOT NULL DEFAULT 'phone', interval_days integer NOT NULL DEFAULT 15, active boolean NOT NULL DEFAULT true);
GRANT SELECT ON public.crm_templates TO authenticated; GRANT ALL ON public.crm_templates TO service_role;
ALTER TABLE public.crm_templates ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.crm_can(_actor uuid,_permission text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM profiles WHERE id=_actor AND status='Đang hoạt động') AND _permission=ANY(ARRAY['biz.crm_use','biz.crm_view_scope','biz.crm_edit_other','biz.crm_transfer','biz.crm_export','biz.crm_archive','biz.crm_settings','biz.crm_access']) AND (biz_admin(_actor) OR CASE WHEN _permission='biz.crm_use' THEN biz_participant(_actor) WHEN _permission='biz.crm_view_scope' THEN biz_manager(_actor) OR biz_all_scope(_actor) WHEN _permission='biz.crm_access' THEN false ELSE EXISTS(SELECT 1 FROM crm_access_grants g WHERE g.user_id=_actor AND g.permission=_permission AND g.revoked_at IS NULL AND g.started_at<=now() AND (g.ended_at IS NULL OR g.ended_at>now()) AND biz_participant(_actor)) END) $$;
CREATE OR REPLACE FUNCTION public.crm_department(_user uuid,_at timestamptz DEFAULT now()) RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT department_id FROM biz_department_members WHERE user_id=_user AND started_at<=_at AND (ended_at IS NULL OR ended_at>_at) ORDER BY started_at DESC,id LIMIT 1 $$;
CREATE OR REPLACE FUNCTION public.crm_owner_visible(_owner uuid,_department uuid DEFAULT NULL,_at timestamptz DEFAULT now()) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT crm_can(auth.uid(),'biz.crm_use') AND (_owner=auth.uid() OR (crm_can(auth.uid(),'biz.crm_view_scope') AND biz_scope_ok(auth.uid(),_owner,coalesce(_department,crm_department(_owner,_at)),_at))) $$;
CREATE OR REPLACE FUNCTION public.crm_customer_visible(_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM crm_customers c WHERE c.id=_id AND crm_owner_visible(c.owner_id)) $$;
CREATE OR REPLACE FUNCTION public.crm_customer_editable(_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM crm_customers c WHERE c.id=_id AND crm_owner_visible(c.owner_id) AND (c.owner_id=auth.uid() OR crm_can(auth.uid(),'biz.crm_edit_other'))) $$;
CREATE POLICY crm_catalog_read ON public.crm_catalogs FOR SELECT TO authenticated USING(crm_can(auth.uid(),'biz.crm_use'));
CREATE POLICY crm_access_read ON public.crm_access_grants FOR SELECT TO authenticated USING(user_id=auth.uid() OR crm_can(auth.uid(),'biz.crm_access'));
CREATE POLICY crm_customer_read ON public.crm_customers FOR SELECT TO authenticated USING(crm_owner_visible(owner_id));
CREATE POLICY crm_contact_read ON public.crm_contacts FOR SELECT TO authenticated USING(crm_customer_visible(customer_id));
CREATE POLICY crm_location_read ON public.crm_locations FOR SELECT TO authenticated USING(crm_customer_visible(customer_id));
CREATE POLICY crm_schedule_read ON public.crm_schedules FOR SELECT TO authenticated USING(crm_customer_visible(customer_id) AND crm_owner_visible(owner_id,department_id,attributed_at));
CREATE POLICY crm_interaction_read ON public.crm_interactions FOR SELECT TO authenticated USING(crm_customer_visible(customer_id) AND crm_owner_visible(owner_id,department_id,happened_at));
CREATE POLICY crm_event_read ON public.crm_events FOR SELECT TO authenticated USING(CASE WHEN customer_id IS NOT NULL THEN crm_customer_visible(customer_id) ELSE crm_can(auth.uid(),'biz.crm_settings') END);
CREATE POLICY crm_template_read ON public.crm_templates FOR SELECT TO authenticated USING(crm_can(auth.uid(),'biz.crm_use') AND (owner_id IS NULL OR owner_id=auth.uid()));
CREATE OR REPLACE FUNCTION private.crm_catalog_validate(_id uuid,_kind text,_old uuid DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF _id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM crm_catalogs WHERE id=_id AND kind=_kind AND (active OR id=_old)) THEN RAISE EXCEPTION 'Danh mục không hợp lệ hoặc đã ngừng sử dụng.'; END IF; END $$;
CREATE OR REPLACE FUNCTION public.crm_catalog_save(_data jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i uuid:=nullif(_data->>'id','')::uuid; p uuid:=nullif(_data->>'parent_id','')::uuid; old jsonb; n text:=trim(_data->>'name'); k text:=_data->>'kind'; BEGIN IF NOT crm_can(auth.uid(),'biz.crm_settings') THEN RAISE EXCEPTION 'Bạn không có quyền cài đặt CRM.'; END IF; PERFORM pg_advisory_xact_lock(hashtext('crm_catalogs')); IF n IS NULL OR n='' OR k<>ALL(ARRAY['group','block','segment','trait','product','need','priority','relationship','source','goal','outcome','contact_role','channel','cooperation','occasion']) THEN RAISE EXCEPTION 'Tên và loại danh mục không hợp lệ.'; END IF; IF i IS NOT NULL THEN SELECT to_jsonb(c) INTO old FROM crm_catalogs c WHERE id=i FOR UPDATE; IF old IS NULL THEN RAISE EXCEPTION 'Danh mục không tồn tại.'; END IF; IF old->>'kind'<>k THEN RAISE EXCEPTION 'Không đổi loại danh mục đã tạo.'; END IF; END IF; IF p IS NOT NULL THEN IF NOT EXISTS(SELECT 1 FROM crm_catalogs WHERE id=p AND active AND kind=ANY(ARRAY['group','block','segment'])) THEN RAISE EXCEPTION 'Nhóm cha không hợp lệ.'; END IF; IF EXISTS(WITH RECURSIVE parents AS (SELECT id,parent_id FROM crm_catalogs WHERE id=p UNION ALL SELECT c.id,c.parent_id FROM crm_catalogs c JOIN parents a ON c.id=a.parent_id) SELECT 1 FROM parents WHERE id=i) THEN RAISE EXCEPTION 'Không được tạo vòng lặp danh mục.'; END IF; END IF; IF EXISTS(SELECT 1 FROM crm_catalogs WHERE kind=k AND parent_id IS NOT DISTINCT FROM p AND lower(name)=lower(n) AND id IS DISTINCT FROM i) THEN RAISE EXCEPTION 'Tên danh mục đã tồn tại trong nhóm này.'; END IF; IF i IS NULL THEN INSERT INTO crm_catalogs(kind,parent_id,name,description,sort_order,active,config) VALUES(k,p,n,coalesce(_data->>'description',''),coalesce((_data->>'sort_order')::int,0),coalesce((_data->>'active')::boolean,true),coalesce(_data->'config','{}')) RETURNING id INTO i; ELSE UPDATE crm_catalogs SET parent_id=p,name=n,description=coalesce(_data->>'description',''),sort_order=coalesce((_data->>'sort_order')::int,0),active=coalesce((_data->>'active')::boolean,true),config=coalesce(_data->'config',config) WHERE id=i; END IF; INSERT INTO crm_events(actor_id,action,before_data,after_data) SELECT auth.uid(),'catalog_save',old,to_jsonb(c) FROM crm_catalogs c WHERE id=i; RETURN i; END $$;
CREATE OR REPLACE FUNCTION public.crm_customer_save(_data jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i uuid:=nullif(_data->>'id','')::uuid; c crm_customers; k uuid:=nullif(_data->>'request_key','')::uuid; g uuid:=nullif(_data->>'group_id','')::uuid; s uuid:=nullif(_data->>'segment_id','')::uuid; pr uuid:=nullif(_data->>'priority_id','')::uuid; rel uuid:=nullif(_data->>'relationship_id','')::uuid; src uuid:=nullif(_data->>'source_id','')::uuid; tags uuid[]:=ARRAY(SELECT jsonb_array_elements_text(coalesce(_data->'related_ids','[]'))::uuid); n text:=trim(_data->>'name'); t uuid; BEGIN IF NOT crm_can(auth.uid(),'biz.crm_use') THEN RAISE EXCEPTION 'Bạn không có quyền sử dụng CRM.'; END IF; PERFORM pg_advisory_xact_lock(hashtext('crm_customer:'||auth.uid())); IF i IS NULL THEN IF k IS NULL THEN RAISE EXCEPTION 'Thiếu mã yêu cầu lưu.'; END IF; SELECT id INTO i FROM crm_customers WHERE created_by=auth.uid() AND request_key=k; IF i IS NOT NULL THEN RETURN i; END IF; ELSE SELECT * INTO c FROM crm_customers WHERE id=i FOR UPDATE; IF NOT FOUND OR NOT crm_customer_editable(i) THEN RAISE EXCEPTION 'Bạn không có quyền sửa khách hàng này.'; END IF; IF c.revision IS DISTINCT FROM (_data->>'revision')::int THEN RAISE EXCEPTION 'Hồ sơ đã thay đổi. Vui lòng tải lại trước khi sửa.'; END IF; END IF; IF n IS NULL OR n='' OR length(n)>300 OR coalesce(_data->>'profile_kind','organization')<>ALL(ARRAY['organization','individual']) THEN RAISE EXCEPTION 'Tên hoặc kiểu khách không hợp lệ.'; END IF; PERFORM private.crm_catalog_validate(g,'group',c.group_id); PERFORM private.crm_catalog_validate(s,'segment',c.segment_id); PERFORM private.crm_catalog_validate(pr,'priority',c.priority_id); PERFORM private.crm_catalog_validate(rel,'relationship',c.relationship_id); PERFORM private.crm_catalog_validate(src,'source',c.source_id); IF s IS NOT NULL AND g IS NOT NULL AND NOT EXISTS(WITH RECURSIVE parents AS (SELECT id,parent_id FROM crm_catalogs WHERE id=s UNION ALL SELECT x.id,x.parent_id FROM crm_catalogs x JOIN parents a ON x.id=a.parent_id) SELECT 1 FROM parents WHERE id=g) THEN RAISE EXCEPTION 'Tệp khách không thuộc nhóm đã chọn.'; END IF; FOREACH t IN ARRAY tags LOOP IF NOT EXISTS(SELECT 1 FROM crm_catalogs WHERE id=t AND (active OR t=ANY(c.related_ids))) THEN RAISE EXCEPTION 'Đặc điểm không hợp lệ.'; END IF; END LOOP; IF c.id IS NULL THEN INSERT INTO crm_customers(owner_id,created_by,request_key,profile_kind,name,phone,tax_code,email,website,legal_name,province_code,ward_code,address,group_id,segment_id,priority_id,relationship_id,source_id,related_ids,details,note) VALUES(auth.uid(),auth.uid(),k,coalesce(_data->>'profile_kind','organization'),n,coalesce(_data->>'phone',''),coalesce(_data->>'tax_code',''),coalesce(_data->>'email',''),coalesce(_data->>'website',''),coalesce(_data->>'legal_name',''),nullif(_data->>'province_code',''),nullif(_data->>'ward_code',''),coalesce(_data->>'address',''),g,s,pr,rel,src,tags,coalesce(_data->'details','{}'),coalesce(_data->>'note','')) RETURNING id INTO i; IF nullif(_data->>'contact_name','') IS NOT NULL THEN INSERT INTO crm_contacts(customer_id,name,phone,is_primary) VALUES(i,_data->>'contact_name',coalesce(_data->>'contact_phone',_data->>'phone',''),true); END IF; ELSE UPDATE crm_customers SET profile_kind=coalesce(_data->>'profile_kind','organization'),name=n,phone=coalesce(_data->>'phone',''),tax_code=coalesce(_data->>'tax_code',''),email=coalesce(_data->>'email',''),website=coalesce(_data->>'website',''),legal_name=coalesce(_data->>'legal_name',''),province_code=nullif(_data->>'province_code',''),ward_code=nullif(_data->>'ward_code',''),address=coalesce(_data->>'address',''),group_id=g,segment_id=s,priority_id=pr,relationship_id=rel,source_id=src,related_ids=tags,details=coalesce(_data->'details','{}'),note=coalesce(_data->>'note',''),revision=revision+1,updated_at=now() WHERE id=i; END IF; INSERT INTO crm_events(customer_id,actor_id,action,before_data,after_data) SELECT i,auth.uid(),'customer_save',CASE WHEN c.id IS NULL THEN NULL ELSE to_jsonb(c) END,to_jsonb(x) FROM crm_customers x WHERE id=i; RETURN i; END $$;
CREATE OR REPLACE FUNCTION public.crm_contact_save(_data jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i uuid:=nullif(_data->>'id','')::uuid; cid uuid:=(_data->>'customer_id')::uuid; old jsonb; BEGIN PERFORM 1 FROM crm_customers WHERE id=cid FOR UPDATE; IF NOT crm_customer_editable(cid) THEN RAISE EXCEPTION 'Không có quyền sửa liên hệ.'; END IF; IF trim(coalesce(_data->>'name',''))='' THEN RAISE EXCEPTION 'Vui lòng nhập tên liên hệ.'; END IF; IF i IS NOT NULL THEN SELECT to_jsonb(c) INTO old FROM crm_contacts c WHERE id=i AND customer_id=cid FOR UPDATE; IF old IS NULL THEN RAISE EXCEPTION 'Liên hệ không thuộc khách hàng.'; END IF; END IF; IF coalesce((_data->>'is_primary')::boolean,false) THEN UPDATE crm_contacts SET is_primary=false WHERE customer_id=cid; END IF; IF i IS NULL THEN INSERT INTO crm_contacts(customer_id,name) VALUES(cid,trim(_data->>'name')) RETURNING id INTO i; END IF; UPDATE crm_contacts SET name=trim(_data->>'name'),phone=coalesce(_data->>'phone',''),zalo=coalesce(_data->>'zalo',''),email=coalesce(_data->>'email',''),title=coalesce(_data->>'title',''),department=coalesce(_data->>'department',''),role_ids=ARRAY(SELECT jsonb_array_elements_text(coalesce(_data->'role_ids','[]'))::uuid),preferred_channel=coalesce(_data->>'preferred_channel','phone'),note=coalesce(_data->>'note',''),active=coalesce((_data->>'active')::boolean,true),is_primary=coalesce((_data->>'is_primary')::boolean,false) WHERE id=i; INSERT INTO crm_events(customer_id,actor_id,action,before_data,after_data) SELECT cid,auth.uid(),'contact_save',old,to_jsonb(c) FROM crm_contacts c WHERE id=i; RETURN i; END $$;
CREATE OR REPLACE FUNCTION public.crm_schedule_save(_data jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i uuid:=nullif(_data->>'id','')::uuid; cid uuid:=(_data->>'customer_id')::uuid; c crm_customers; old crm_schedules; due timestamptz:=(_data->>'due_at')::timestamptz; k text:=_data->>'kind'; contact uuid:=nullif(_data->>'contact_id','')::uuid; req uuid:=nullif(_data->>'request_key','')::uuid; days int:=nullif(_data->>'interval_days','')::int; BEGIN SELECT * INTO c FROM crm_customers WHERE id=cid FOR UPDATE; IF NOT FOUND OR c.archived_at IS NOT NULL OR NOT crm_customer_editable(cid) THEN RAISE EXCEPTION 'Không có quyền lập lịch cho khách này.'; END IF; IF i IS NULL THEN IF req IS NULL THEN RAISE EXCEPTION 'Thiếu mã yêu cầu.'; END IF; SELECT id INTO i FROM crm_schedules WHERE created_by=auth.uid() AND request_key=req; IF i IS NOT NULL THEN RETURN i; END IF; ELSE SELECT * INTO old FROM crm_schedules WHERE id=i AND customer_id=cid FOR UPDATE; IF NOT FOUND OR old.status<>'pending' THEN RAISE EXCEPTION 'Chỉ sửa lịch chưa xử lý.'; END IF; IF old.revision IS DISTINCT FROM (_data->>'revision')::int THEN RAISE EXCEPTION 'Lịch đã thay đổi. Vui lòng tải lại.'; END IF; IF old.due_at IS DISTINCT FROM due AND trim(coalesce(_data->>'reason',''))='' THEN RAISE EXCEPTION 'Vui lòng nhập lý do dời lịch.'; END IF; END IF; IF due IS NULL OR k<>ALL(ARRAY['appointment','recurring','seasonal']) OR (k='recurring' AND (days IS NULL OR days<1 OR days>3660)) THEN RAISE EXCEPTION 'Lịch hoặc chu kỳ không hợp lệ.'; END IF; IF contact IS NOT NULL AND NOT EXISTS(SELECT 1 FROM crm_contacts WHERE id=contact AND customer_id=cid) THEN RAISE EXCEPTION 'Liên hệ không thuộc khách này.'; END IF; IF i IS NULL THEN INSERT INTO crm_schedules(customer_id,contact_id,kind,goal,content,channel,interval_days,fixed_weekday,due_at,original_due_at,reminder_days,owner_id,department_id,created_by,request_key) VALUES(cid,contact,k,coalesce(_data->>'goal',''),coalesce(_data->>'content',''),coalesce(_data->>'channel','phone'),days,nullif(_data->>'fixed_weekday','')::int,due,due,greatest(0,coalesce((_data->>'reminder_days')::int,0)),c.owner_id,crm_department(c.owner_id),auth.uid(),req) RETURNING id INTO i; ELSE UPDATE crm_schedules SET contact_id=contact,kind=k,goal=coalesce(_data->>'goal',''),content=coalesce(_data->>'content',''),channel=coalesce(_data->>'channel','phone'),interval_days=days,fixed_weekday=nullif(_data->>'fixed_weekday','')::int,due_at=due,reminder_days=greatest(0,coalesce((_data->>'reminder_days')::int,0)),revision=revision+1 WHERE id=i; END IF; INSERT INTO crm_events(customer_id,schedule_id,actor_id,action,before_data,after_data,reason) SELECT cid,i,auth.uid(),'schedule_save',CASE WHEN old.id IS NULL THEN NULL ELSE to_jsonb(old) END,to_jsonb(s),coalesce(_data->>'reason','') FROM crm_schedules s WHERE id=i; RETURN i; END $$;
CREATE OR REPLACE FUNCTION public.crm_interaction_save(_data jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid:=(_data->>'customer_id')::uuid; sid uuid:=nullif(_data->>'schedule_id','')::uuid; req uuid:=(_data->>'request_key')::uuid; contact uuid:=nullif(_data->>'contact_id','')::uuid; outcome uuid:=(_data->>'outcome_id')::uuid; cfg jsonb; c crm_customers; s crm_schedules; i uuid; nextid uuid; nextat timestamptz; conn boolean; done boolean; act text:=coalesce(_data->>'next_action','keep'); BEGIN SELECT * INTO c FROM crm_customers WHERE id=cid FOR UPDATE; IF NOT FOUND OR NOT crm_customer_editable(cid) OR c.archived_at IS NOT NULL THEN RAISE EXCEPTION 'Không có quyền cập nhật chăm sóc.'; END IF; IF req IS NULL THEN RAISE EXCEPTION 'Thiếu mã yêu cầu.'; END IF; SELECT id INTO i FROM crm_interactions WHERE actor_id=auth.uid() AND request_key=req; IF i IS NOT NULL THEN RETURN i; END IF; IF sid IS NOT NULL THEN SELECT * INTO s FROM crm_schedules WHERE id=sid AND customer_id=cid FOR UPDATE; IF NOT FOUND OR s.status<>'pending' OR s.revision IS DISTINCT FROM (_data->>'revision')::int THEN RAISE EXCEPTION 'Lịch đã được thay đổi hoặc xử lý. Vui lòng tải lại.'; END IF; END IF; IF contact IS NOT NULL AND NOT EXISTS(SELECT 1 FROM crm_contacts WHERE id=contact AND customer_id=cid) THEN RAISE EXCEPTION 'Liên hệ không thuộc khách hàng.'; END IF; SELECT config INTO cfg FROM crm_catalogs WHERE id=outcome AND kind='outcome' AND active; IF cfg IS NULL OR trim(coalesce(_data->>'content',''))='' THEN RAISE EXCEPTION 'Vui lòng chọn kết quả và nhập nội dung trao đổi.'; END IF; IF act<>ALL(ARRAY['keep','continue','date','pause']) THEN RAISE EXCEPTION 'Bước tiếp theo không hợp lệ.'; END IF; conn:=coalesce((cfg->>'connected')::boolean,false); done:=conn AND coalesce((cfg->>'completed')::boolean,false); IF act='continue' AND (NOT done OR s.id IS NULL OR s.kind<>'recurring') THEN RAISE EXCEPTION 'Chỉ tiếp tục chu kỳ sau lần hoàn tất hợp lệ.'; END IF; IF act='pause' AND trim(coalesce(_data->>'reason',''))='' THEN RAISE EXCEPTION 'Vui lòng nhập lý do tạm ngừng.'; END IF; IF act='date' THEN nextat:=(_data->>'next_at')::timestamptz; IF nextat IS NULL OR nextat<=now() THEN RAISE EXCEPTION 'Lịch tiếp theo phải ở tương lai.'; END IF; ELSIF act='continue' THEN nextat:=now()+make_interval(days=>coalesce(nullif(_data->>'interval_days','')::int,s.interval_days)); IF s.fixed_weekday IS NOT NULL THEN nextat:=((now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date+greatest(1,((s.fixed_weekday-extract(dow FROM now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::int+7)%7)))::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh'; END IF; END IF; IF s.id IS NOT NULL THEN UPDATE crm_schedules SET processed_at=coalesce(processed_at,now()),completed_at=CASE WHEN done THEN now() ELSE completed_at END,status=CASE WHEN act='pause' THEN 'paused' WHEN done OR act='date' THEN 'processed' ELSE 'pending' END,revision=revision+1 WHERE id=sid; END IF; IF nextat IS NOT NULL THEN INSERT INTO crm_schedules(customer_id,contact_id,kind,goal,content,channel,interval_days,fixed_weekday,due_at,original_due_at,owner_id,department_id,created_by,request_key) VALUES(cid,contact,CASE WHEN act='continue' THEN 'recurring' ELSE 'appointment' END,coalesce(_data->>'next_goal',s.goal,''),coalesce(_data->>'next_content',''),coalesce(_data->>'channel','phone'),CASE WHEN act='continue' THEN coalesce(nullif(_data->>'interval_days','')::int,s.interval_days) ELSE NULL END,s.fixed_weekday,nextat,nextat,c.owner_id,crm_department(c.owner_id),auth.uid(),req) RETURNING id INTO nextid; END IF; INSERT INTO crm_interactions(customer_id,schedule_id,contact_id,actor_id,owner_id,department_id,channel,outcome_id,connected,completed,content,next_schedule_id,request_key) VALUES(cid,sid,contact,auth.uid(),c.owner_id,crm_department(c.owner_id),coalesce(_data->>'channel','phone'),outcome,conn,done,_data->>'content',nextid,req) RETURNING id INTO i; INSERT INTO crm_events(customer_id,schedule_id,actor_id,action,before_data,after_data,reason) VALUES(cid,sid,auth.uid(),'interaction',CASE WHEN s.id IS NULL THEN NULL ELSE to_jsonb(s) END,jsonb_build_object('interaction_id',i,'next_schedule_id',nextid,'connected',conn,'completed',done),coalesce(_data->>'reason','')); RETURN i; END $$;
CREATE OR REPLACE FUNCTION public.crm_customer_action(_id uuid,_revision int,_action text,_reason text,_owner uuid DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c crm_customers; BEGIN SELECT * INTO c FROM crm_customers WHERE id=_id FOR UPDATE; IF NOT FOUND OR NOT crm_customer_visible(_id) OR c.revision<>_revision OR trim(coalesce(_reason,''))='' THEN RAISE EXCEPTION 'Hồ sơ đã thay đổi, ngoài phạm vi hoặc thiếu lý do.'; END IF; IF _action='transfer' THEN IF NOT crm_can(auth.uid(),'biz.crm_transfer') OR NOT crm_owner_visible(_owner) OR NOT crm_can(_owner,'biz.crm_use') THEN RAISE EXCEPTION 'Không có quyền bàn giao trong phạm vi này.'; END IF; UPDATE crm_customers SET owner_id=_owner,revision=revision+1,updated_at=now() WHERE id=_id; UPDATE crm_schedules SET owner_id=_owner,department_id=crm_department(_owner),attributed_at=now(),revision=revision+1 WHERE customer_id=_id AND status='pending' AND original_due_at>now(); ELSIF _action=ANY(ARRAY['archive','restore']) THEN IF NOT crm_can(auth.uid(),'biz.crm_archive') THEN RAISE EXCEPTION 'Không có quyền lưu trữ khách.'; END IF; UPDATE crm_customers SET archived_at=CASE WHEN _action='archive' THEN now() ELSE NULL END,revision=revision+1,updated_at=now() WHERE id=_id; ELSE RAISE EXCEPTION 'Thao tác không hợp lệ.'; END IF; INSERT INTO crm_events(customer_id,actor_id,action,before_data,after_data,reason) SELECT _id,auth.uid(),_action,to_jsonb(c),to_jsonb(x),_reason FROM crm_customers x WHERE id=_id; END $$;
CREATE OR REPLACE FUNCTION public.crm_access_save(_data jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i uuid; u uuid:=(_data->>'user_id')::uuid; p text:=_data->>'permission'; e timestamptz:=nullif(_data->>'ended_at','')::timestamptz; BEGIN IF NOT crm_can(auth.uid(),'biz.crm_access') THEN RAISE EXCEPTION 'Chỉ Admin/Super Admin được cấp quyền CRM.'; END IF; IF p<>ALL(ARRAY['biz.crm_edit_other','biz.crm_transfer','biz.crm_export','biz.crm_archive','biz.crm_settings']) OR trim(coalesce(_data->>'reason',''))='' OR NOT crm_can(u,'biz.crm_use') OR (e IS NOT NULL AND e<=now()) THEN RAISE EXCEPTION 'Quyền, nhân sự, thời hạn hoặc lý do không hợp lệ.'; END IF; IF nullif(_data->>'revoke_id','') IS NOT NULL THEN UPDATE crm_access_grants SET revoked_at=now() WHERE id=(_data->>'revoke_id')::uuid AND user_id=u; ELSE INSERT INTO crm_access_grants(user_id,permission,ended_at,reason,granted_by) VALUES(u,p,e,_data->>'reason',auth.uid()) RETURNING id INTO i; END IF; INSERT INTO crm_events(actor_id,action,after_data,reason) VALUES(auth.uid(),'access_save',_data,_data->>'reason'); RETURN i; END $$;
DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.biz_effective_access(uuid)'::regprocedure) INTO d; IF position('public.crm_can' in d)=0 THEN d:=replace(d,'SELECT p FROM unnest(ARRAY[''k3.use'',''k3.view_scope'',''k3.comment'',''k3.settings'']) p WHERE public.k3_can(u,p)','SELECT p FROM unnest(ARRAY[''k3.use'',''k3.view_scope'',''k3.comment'',''k3.settings'']) p WHERE public.k3_can(u,p) UNION ALL SELECT p FROM unnest(ARRAY[''biz.crm_use'',''biz.crm_view_scope'',''biz.crm_edit_other'',''biz.crm_transfer'',''biz.crm_export'',''biz.crm_archive'',''biz.crm_settings'',''biz.crm_access'']) p WHERE public.crm_can(u,p)'); IF position('public.crm_can' in d)=0 THEN RAISE EXCEPTION 'Không tìm thấy điểm bổ sung quyền CRM.'; END IF; EXECUTE d; END IF; END $$;
REVOKE ALL ON FUNCTION private.crm_catalog_validate(uuid,text,uuid) FROM PUBLIC,anon,authenticated;
DO $$ DECLARE r record; BEGIN FOR r IN SELECT p.oid::regprocedure AS fn FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname LIKE 'crm_%' LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon',r.fn); EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO authenticated,service_role',r.fn); END LOOP; END $$;